}

.voice-wave span {
    width: 2px;
    height: 8px;
    background: white;
    border-radius: 1px;
    transition: all 0.3s ease;
}

.voice-message-container.playing .voice-wave span {
    animation: voice-wave 1s ease-in-out infinite;
}

.voice-wave span:nth-child(1) { height: 6px; }
.voice-wave span:nth-child(2) { height: 10px; }
.voice-wave span:nth-child(3) { height: 8px; }

.voice-duration {
    font-size: 13px;
