    font-weight: 500;
    min-width: 36px;
    text-align: right;
    position: relative;
    padding-right: 18px;
    margin-left: auto;
}

.voice-duration::after {
    content: '';
    position: absolute;
    right: 0;
    top: 50%;
    transform: translateY(-50%);
    width: 14px;
