    background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="%236C8CD5"><path d="M8 5v14l11-7z"/></svg>') no-repeat center;
    background-size: contain;
    opacity: 0.7;
    transition: all 0.3s ease;
}

.voice-message-container.playing .voice-duration::after {
    background-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="%236C8CD5"><path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z"/></svg>');
