function playVoice(container) {
    const audio = container.querySelector('.voice-audio');
    const durationElement = container.querySelector('.voice-duration');
    const allContainers = document.querySelectorAll('.voice-message-container');

    // 当音频元数据加载完成后，更新显示时间和容器宽度
    audio.onloadedmetadata = () => {
        const duration = Math.round(audio.duration);
        const minutes = Math.floor(duration / 60);
        const seconds = duration % 60;
        durationElement.textContent = `${minutes}:${seconds.toString().padStart(2, '0')}`;

        // 设置容器宽度
        container.style.setProperty('--duration', duration);
    };

    // 确保有进度条元素
    let progressBar = container.querySelector('.voice-progress');
    if (!progressBar) {
        progressBar = document.createElement('div');
        progressBar.className = 'voice-progress';
        container.appendChild(progressBar);
    }

    // 停止所有其他正在播放的语音
    allContainers.forEach(otherContainer => {
        if (otherContainer !== container) {
            otherContainer.classList.remove('playing');
            const otherAudio = otherContainer.querySelector('.voice-audio');
            const otherProgress = otherContainer.querySelector('.voice-progress');
            if (otherProgress) otherProgress.style.width = '0%';
            otherAudio.pause();
        }
    });

    if (audio.paused) {
        container.classList.add('playing');
        audio.play().catch(e => console.log('播放失败:', e));

        // 更新进度条
        audio.ontimeupdate = () => {
            const percent = (audio.currentTime / audio.duration) * 100;
            progressBar.style.width = `${percent}%`;
        };

        audio.onended = () => {
            container.classList.remove('playing');
            progressBar.style.width = '0%';
            audio.currentTime = 0; // 播放结束时重置时间
        };
    } else {
        container.classList.remove('playing');
        audio.pause();
        // 移除重置currentTime的代码，这样暂停后会从暂停处继续播放
    }
}

// 添加语音时长加载完成后的处理函数
function updateDuration(audio) {
    const container = audio.closest('.voice-message-container');
    const durationElement = container.querySelector('.voice-duration');
    const duration = Math.round(audio.duration);
    const minutes = Math.floor(duration / 60);
    const seconds = duration % 60;
    durationElement.textContent = `${minutes}:${seconds.toString().padStart(2, '0')}`;

    // 设置容器宽度
    container.style.setProperty('--duration', duration);
}
