    <script>
        function triggerActionWithSound(action) {
    const audio = document.getElementById('clickSound');
    audio.currentTime = 0;
    audio.play();
    if (action === 'hideNewChatModal') {
        hideNewChatModal();
    } else if (action === 'createNewChat') {
        createNewChat();
    } else if (typeof triggerSlash === 'function') {
        triggerSlash(action);
    }
}

function showNewChatModal() {
    const audio = document.getElementById('clickSound');
    audio.currentTime = 0;
    audio.play();
    document.getElementById('newChatModal').style.display = 'flex';
}

function hideNewChatModal() {
    document.getElementById('newChatModal').style.display = 'none';
    resetModal();
}

let currentChatType = 'single';
let selectedContacts = new Set();

function selectChatType(element, type) {
    document.querySelectorAll('.chat-type-option').forEach(option => {
        option.classList.remove('selected');
    });
    element.classList.add('selected');
    currentChatType = type;
    const contactList = document.querySelector('.contact-list');
    if (type === 'group') {
        contactList.classList.add('group-mode');
    } else {
        contactList.classList.remove('group-mode');
        selectedContacts.clear();
        document.querySelectorAll('.contact-item').forEach(item => {
            item.classList.remove('selected');
        });
    }
}

function toggleContact(element) {
    if (currentChatType === 'single') {
        document.querySelectorAll('.contact-item').forEach(item => {
            item.classList.remove('selected');
        });
        element.classList.add('selected');
        selectedContacts.clear();
        selectedContacts.add(element.dataset.name);
    } else {
        element.classList.toggle('selected');
        if (element.classList.contains('selected')) {
            selectedContacts.add(element.dataset.name);
        } else {
            selectedContacts.delete(element.dataset.name);
        }
    }
}

function createNewChat() {
    if (selectedContacts.size === 0) {
        alert('请选择联系人');
        return;
    }
    if (currentChatType === 'single') {
        const contact = Array.from(selectedContacts)[0];
        if (typeof triggerSlash === 'function') {
            triggerSlash(`/send 查看${contact}发来的消息|/trigger`);
        }
    } else {
        const contacts = Array.from(selectedContacts).join(' ');
        if (typeof triggerSlash === 'function') {
            triggerSlash(`/send 和${contacts}建立群聊|/trigger`);
        }
    }
    hideNewChatModal();
}

function resetModal() {
    currentChatType = 'single';
    selectedContacts.clear();
    document.querySelectorAll('.chat-type-option').forEach(option => {
        option.classList.remove('selected');
    });
    document.querySelector('.chat-type-option[onclick*="single"]').classList.add('selected');
    document.querySelectorAll('.contact-item').forEach(item => {
        item.classList.remove('selected');
    });
    document.querySelector('.contact-list').classList.remove('group-mode');
}

document.addEventListener('DOMContentLoaded', function() {
    resetModal();
});

document.addEventListener('DOMContentLoaded', function() {
    // 为所有聊天项添加点击事件
    document.querySelectorAll('.chat-list-item').forEach(item => {
        item.addEventListener('click', function() {
            const name = this.getAttribute('data-name');
            const unread = this.getAttribute('data-unread');
            const message = `查看${name}发来的消息 ${unread}条`;

            // 播放音效
            const audio = document.getElementById('clickSound');
            audio.currentTime = 0;
            audio.play();

            // 发送消息到聊天系统
            if(typeof triggerSlash === 'function') {
                triggerSlash(`/send ${message}|/trigger`);
            }
        });
    });
});
    </script>
