        setTimeout(() => {
            pathLine.setAttribute('d', '');
            isMoving = false;
        }, 500);
    }
});

            }
        });

        generateStoryPoints();
    }

    // 每50秒重新生成一次角色分布和剧情点
    setInterval(generateCharacters, 50000);
    generateCharacters();

    // 返回按钮点击事件
    backButton.addEventListener('click', function(e) {
        playClickSound();
        if (typeof triggerSlash === 'function') {
            triggerSlash('/send 返回主页|/trigger');
        }
    });

    // 地点标记点击事件
locationMarkers.forEach(marker => {
    marker.addEventListener('click', function(e) {
        e.stopPropagation();
        playClickSound();
        if (isMoving) return;

        const locationName = this.getAttribute('data-location');

        // 如果是随机地点，显示弹窗
        if (locationName === '随机地点') {
            createRandomLocationDialog();
            return;
        }

        const rect = mapContent.getBoundingClientRect();
        const markerRect = this.getBoundingClientRect();

        const x = markerRect.left + markerRect.width/2 - rect.left;
        const y = markerRect.top + markerRect.height/2 - rect.top;

        const playerRect = player.getBoundingClientRect();
        const startX = playerRect.left + playerRect.width/2 - rect.left;  // 添加这行
        const startY = playerRect.top + playerRect.height/2 - rect.top;   // 添加这行

        pathLine.setAttribute('d', `M ${startX} ${startY} L ${x} ${y}`);

        isMoving = true;
        player.style.left = `${(x/rect.width) * 100}%`;
        player.style.top = `${(y/rect.height) * 100}%`;

        const charactersHere = [];
        for (const [charName, location] of characterLocations.entries()) {
            if (location === locationName) {
                charactersHere.push(charName);
            }
        }

        if (typeof triggerSlash === 'function') {
            const importance = storyPoints.get(locationName);
            let message;
            if (charactersHere.length > 0) {
                message = `出发去${locationName} 遇见了${charactersHere.join('、')}${importance ? '[!]'.repeat(importance) : ''}`;
            } else {
                message = `出发去${locationName}${importance ? '[!]'.repeat(importance) : ''}`;
            }
            triggerSlash(`/send ${message}|/trigger`);
        }

        setTimeout(() => {
            pathLine.setAttribute('d', '');
            isMoving = false;
        }, 500);
    });
});


    // 地图空白处点击事件
    mapContent.addEventListener('click', function(e) {
        playClickSound();
        if (isMoving) return;
        if (e.target === this || e.target.classList.contains('map-decoration')) {
            const rect = mapContent.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const playerRect = player.getBoundingClientRect();
            const startX = playerRect.left + playerRect.width/2 - rect.left;
            const startY = playerRect.top + playerRect.height/2 - rect.top;

            pathLine.setAttribute('d', `M ${startX} ${startY} L ${x} ${y}`);

            isMoving = true;
            player.style.left = `${(x/rect.width) * 100}%`;
            player.style.top = `${(y/rect.height) * 100}%`;

            setTimeout(() => {
                pathLine.setAttribute('d', '');
                isMoving = false;
            }, 500);
        }
    });

    // 给所有可点击元素添加音效
    document.querySelectorAll('.location-marker, .back-button').forEach(element => {
        element.addEventListener('click', playClickSound);
    });
});

</script>
</body>
</html>
