    <script>
        const slider = document.getElementById('slider');
        let isDragging = false;
        let startX;
        let sliderLeft;

        slider.addEventListener('mousedown', startDragging);
        document.addEventListener('mousemove', drag);
        document.addEventListener('mouseup', stopDragging);

        slider.addEventListener('touchstart', startDragging);
        document.addEventListener('touchmove', drag);
        document.addEventListener('touchend', stopDragging);

        function startDragging(e) {
            isDragging = true;
            startX = e.type === 'mousedown' ? e.pageX : e.touches[0].pageX;
            sliderLeft = slider.offsetLeft;
        }

        function drag(e) {
            if (!isDragging) return;

            e.preventDefault();
            const x = e.type === 'mousemove' ? e.pageX : e.touches[0].pageX;
            const walk = x - startX;
            let newLeft = sliderLeft + walk;

            const container = slider.parentElement;
            const maxLeft = container.offsetWidth - slider.offsetWidth - 5;
            newLeft = Math.max(5, Math.min(newLeft, maxLeft));

            slider.style.left = `${newLeft}px`;

            if (newLeft >= maxLeft) {
                playRandomSound();
                if (typeof triggerSlash === 'function') {
                    triggerSlash('/send 【手机屏幕】');
                }
                stopDragging();
                setTimeout(() => {
                    slider.style.left = '5px';
                }, 500);
            }
        }

        const soundEffects = [
            'https://files.catbox.moe/hpi9ew.wav',
        ].map(url => {
            const audio = new Audio(url);
            audio.load();
            return audio;
        });

        function playRandomSound() {
            const randomIndex = Math.floor(Math.random() * soundEffects.length);
            soundEffects[randomIndex].currentTime = 0;
            soundEffects[randomIndex].play();
        }

        function stopDragging() {
            isDragging = false;
        }

        function createCherryBlossom() {
            const blossom = document.createElement('div');
            blossom.classList.add('cherry-blossom');
            blossom.style.left = Math.random() * 100 + 'vw';
            const size = Math.random() * 15 + 5;
            blossom.style.width = size + 'px';
            blossom.style.height = size + 'px';
            blossom.style.animationDuration = (Math.random() * 5 + 4) + 's';
            blossom.style.opacity = Math.random() * 0.5 + 0.3;
            const pink = Math.random() * 15 + 187;
            blossom.style.background = `rgba(255, ${pink}, ${pink + 10}, 0.8)`;
            blossom.style.borderRadius = '50%';
            blossom.style.filter = 'blur(1.5px)';
            document.body.appendChild(blossom);
            setTimeout(() => {
                blossom.remove();
            }, parseFloat(blossom.style.animationDuration) * 1000);
        }

        setInterval(createCherryBlossom, 800);
    </script>
