        if (avatar.parentElement.querySelector('.character-name').textContent === characterName) {
            avatar.classList.add('pulse');
            setTimeout(() => avatar.classList.remove('pulse'), 500);
        }
    });

    // 发送消息到聊天
    sendMessage(`观察${characterName}的实时状况`);
}

// 发送消息函数
function sendMessage(message) {
    console.log(`发送消息: ${message}`);

    // 如果在SillyTavern环境中，使用其API
    if (window.parent) {
        try {
            // 尝试通过postMessage发送
            window.parent.postMessage({
                type: 'sendMessage',
                message: message
            }, '*');

            // 备用方法：如果存在triggerSlash函数
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${message}|/trigger`);
            }
        } catch (error) {
            console.error('发送消息失败:', error);
        }
    }
}
</script>
</body>
</html>
