/* 通话弹窗容器 */
.voice-call-modal {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 90%;
    max-width: 320px;
    background: rgba(255, 255, 255, 0.95);
