    const sendBtn = document.querySelector('.send-btn');
    const chatMessages = document.querySelector('.chat-messages');
    const homeBtn = document.querySelector('.home-btn');
    const callBtn = document.querySelector('.call-btn');
    const avatars = document.querySelectorAll('.avatar');
    const messageContents = document.querySelectorAll('.message-content');

    // 音效对象
    const sounds = {
        click: new Audio('https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3'),
        send: new Audio('https://files.catbox.moe/ub6b6b.mp3'),
        emoji: new Audio('https://files.catbox.moe/gb0so5.mp3'),
        bubble: new Audio('https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3'),
        avatar: new Audio('https://assets.mixkit.co/active_storage/sfx/2568/2568-preview.mp3')
    };

    // 播放音效的函数
    function playSound(soundType) {
        const sound = sounds[soundType];
        if(sound) {
            sound.currentTime = 0;
            sound.play().catch(err => console.log('音频播放失败:', err));
        }
    }

    // 修改表情选择器样式
    const style = document.createElement('style');
    style.textContent = `
        .emoji-picker-container {
            position: absolute;
            bottom: 60px;
            left: 16px;
            display: none;
            z-index: 1000;
            max-height: 300px;
