         // 向聊天系统发送消息
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send 回复和许梦澜的聊天：${messageText}|/trigger`);
            }

        // 获取最后一条消息的时间
        const lastMessage = chatMessages.querySelector('.message:last-child');
