        if (callTimeout) {
            clearTimeout(callTimeout);
        }
    });

    // 生成2-7秒的随机等待时间
    const randomWaitTime = Math.floor(Math.random() * (7000 - 2000 + 1) + 2000);

    // 随机时间后决定接听或拒绝
    callTimeout = setTimeout(() => {
        const randomNum = Math.random();
        modal.style.display = 'none';
        callAudio.pause();
        if (randomNum <= 0.9) { // 90%概率接听
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${chatName}接听了语音通话|/trigger`);
            }
        } else { // 10%概率拒绝
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${chatName}拒绝了语音通话|/trigger`);
            }
        }
    }, randomWaitTime);
});

// ... existing code ...

    // 点击其他地方关闭表情选择器
    document.addEventListener('click', (e) => {
        if (!emojiBtn.contains(e.target) && !emojiPickerContainer.contains(e.target)) {
            emojiPickerContainer.style.display = 'none';
        }
    });

    // 预加载音频
    Object.values(sounds).forEach(sound => {
        sound.load();
    });

    // 动态监听新添加的消息
    const observer = new MutationObserver((mutations) => {
        mutations.forEach((mutation) => {
            if (mutation.addedNodes.length) {
                mutation.addedNodes.forEach((node) => {
                    if (node.nodeType === 1) { // 元素节点
                        const newAvatars = node.querySelectorAll('.avatar');
                        const newContents = node.querySelectorAll('.message-content');

                        newAvatars.forEach(avatar => {
                            avatar.addEventListener('click', () => {
                                playSound('avatar');
                            });
                        });

                        newContents.forEach(content => {
                            content.addEventListener('click', () => {
                                playSound('bubble');
                            });
                        });
                    }
                });
            }
        });
    });

    observer.observe(chatMessages, {
        childList: true,
        subtree: true
    });
});

// 存储对方的所有消息
const receivedMessages = Array.from(document.querySelectorAll('.message.received'));

// 创建音效对象
const messageSound = new Audio('https://files.catbox.moe/ub6b6b.mp3');

// 检查是否是最新的界面
function isLatestInterface() {
    const currentTimestamp = Date.now();
    const lastTimestamp = parseInt(localStorage.getItem('lastInterfaceTimestamp') || '0');

    // 更新时间戳
    localStorage.setItem('lastInterfaceTimestamp', currentTimestamp.toString());

    // 如果当前时间戳与上一个时间戳相差不到100ms，说明是同一个界面的复制
    return (currentTimestamp - lastTimestamp) > 100;
}

function showMessages() {
    // 检查是否有我方消息
    const hasSentMessages = document.querySelectorAll('.message.sent').length > 0;

    // 检查是否是最新界面
    const isLatest = isLatestInterface();

    if (!isLatest || !hasSentMessages) {
        // 不是最新界面或没有我方消息时，直接显示所有消息
        receivedMessages.forEach(msg => {
            msg.style.display = 'flex';
        });
        return;
    }

    // 最新界面且有我方消息时，使用渐进显示效果
    receivedMessages.forEach(msg => {
        msg.style.display = 'none';
    });

    // 随机打字时间（1-4秒）
    function getRandomTypingTime() {
        return Math.floor(Math.random() * (4000 - 1000 + 1) + 1000);
    }

    // 随机消息间隔时间（0.5-1.5秒）
    function getRandomDelay() {
        return Math.floor(Math.random() * (1500 - 500 + 1) + 500);
    }

    // 处理特殊消息内容
    function isSpecialContent(content) {
        return content.includes('random-image-container') ||
               content.includes('typing-indicator') ||
               content.includes('<div') ||
               content.includes('<img') ||
               content.includes('recalled');  // 添加对撤回消息的判断
    }

    // 打字动画效果
    // 在文件中搜索 "function typeMessage"，将整个函数替换为：
function typeMessage(messageContent, originalContent, onComplete) {
    // 判断是否是撤回消息
    const isRecalled = originalContent.includes('此消息已撤回');

    if (isRecalled) {
        handleRecalledMessage(messageContent, originalContent);
        setTimeout(onComplete, 3000); // 等待撤回动画完成后继续
        return;
    }

    // 检查是否包含特殊内容
    if (isSpecialContent(originalContent)) {
        // 如果是特殊内容，直接显示原始HTML
        messageContent.innerHTML = originalContent;
        messageSound.currentTime = 0;
        messageSound.play();
        onComplete();
        return;
    }

    const typingIndicator = document.createElement('div');
    typingIndicator.className = 'typing-indicator';
    typingIndicator.innerHTML = '<span class="typing-dot"></span><span class="typing-dot"></span><span class="typing-dot"></span>';

    messageContent.textContent = '';
    messageContent.appendChild(typingIndicator);

       // 随机打字时间
const typingTime = getRandomTypingTime();

setTimeout(() => {
    // 渐变过渡效果
    typingIndicator.style.transition = 'opacity 0.5s';
    typingIndicator.style.opacity = '0';

    setTimeout(() => {
        typingIndicator.remove();
        messageContent.textContent = '';

        let charIndex = 0;
        let hasPlayedSound = false;
        const typeChar = () => {
            if (charIndex < originalContent.length) {
                // 在第一个字符出现时播放音效
                if (!hasPlayedSound) {
                    messageSound.currentTime = 0;
                    messageSound.play();
                    hasPlayedSound = true;
                }
                messageContent.textContent += originalContent.charAt(charIndex);
                charIndex++;
                setTimeout(typeChar, 50);
            } else {
                onComplete();
            }
        };
        typeChar();

    }, 500);

}, typingTime);
    }

function handleRecalledMessage(messageContent, originalContent) {
    // 获取原始消息内容
    const recalledTooltip = messageContent.closest('.message-wrapper').querySelector('.recalled-tooltip');
    let originalText = '';
    if (recalledTooltip) {
        // 从 recalled-tooltip 中提取出原始消息内容
        originalText = recalledTooltip.textContent.replace('原消息：', '').trim();
    }

    // 创建打字指示器
    const typingIndicator = document.createElement('div');
    typingIndicator.className = 'typing-indicator';
    typingIndicator.innerHTML = '<span class="typing-dot"></span><span class="typing-dot"></span><span class="typing-dot"></span>';

    messageContent.textContent = '';
    messageContent.appendChild(typingIndicator);
