        setTimeout(() => {
            notification.style.animation = 'pokeOut 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55)';
            setTimeout(() => {
                notification.style.display = 'none';
            }, 300);
        }, 2000);
    }

    // 随机戳一戳功能
    function randomPoke() {
        const now = new Date().getTime();
        if (now - lastPokeTime >= 3000) {
            lastPokeTime = now;
            const randomActions = [
                "上官烟然戳了戳你的头像",
                "上官烟然拍了拍你的头",
