    background-repeat: no-repeat;
    z-index: 9999;
    pointer-events: none;
}

.phone-notch {
    position: absolute;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 160px;
    height: 13px;
    background: #363636;
    border-bottom-left-radius: 12px;
    border-bottom-right-radius: 12px;
    z-index: 2;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 8px;
}

.notch-forum {
    width: 8px;
    height: 8px;
    background: #222;
    border-radius: 50%;
    border: 2px solid #444;
}

.notch-speaker {
    width: 40px;
    height: 4px;
    background: #222;
    border-radius: 2px;
}

.notch-sensor {
    width: 6px;
    height: 6px;
    background: #222;
    border-radius: 50%;
    border: 1px solid #444;
}

.status-bar {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 24px;
    background: rgba(255, 192, 203, 0.3);
    backdrop-filter: blur(5px);
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 16px;
    color: #444;
    font-size: 12px;
    z-index: 1;
}

.status-bar-left {
    display: flex;
    align-items: center;
    gap: 4px;
}

.status-bar-right {
    display: flex;
    align-items: center;
    gap: 8px;
}

.status-icon-svg {
    width: 16px;
    height: 16px;
    fill: #444;
}

/* Map specific styles */
.map-container {
    position: relative;
    width: 100%;
    height: calc(100% - 24px);
    margin-top: 24px;
    background: linear-gradient(135deg, #fff5f5 0%, #fff0f5 100%);
    overflow: hidden;
}

.map-decoration {
    position: absolute;
    width: 100%;
    height: 100%;
    pointer-events: none;
    background-image:
        radial-gradient(circle at 10% 10%, rgba(255,182,193,0.1) 0%, transparent 50%),
        radial-gradient(circle at 90% 90%, rgba(255,192,203,0.1) 0%, transparent 50%);
}

.back-button {
    position: absolute;
    top: 10px;
    left: 10px;
    z-index: 10;
    background: rgba(255, 255, 255, 0.9);
    border: none;
    padding: 8px 16px;
    border-radius: 20px;
    box-shadow: 0 2px 8px rgba(255,182,193,0.3);
    cursor: pointer;
    font-size: 14px;
    display: flex;
    align-items: center;
    gap: 4px;
    color: #ff6b88;
    transition: all 0.3s ease;
}

.back-button:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(255,182,193,0.4);
}

.map-content {
    width: 100%;
    height: 100%;
    background-image:
        linear-gradient(45deg, rgba(255,192,203,0.1) 25%, transparent 25%),
        linear-gradient(-45deg, rgba(255,192,203,0.1) 25%, transparent 25%),
        linear-gradient(45deg, transparent 75%, rgba(255,192,203,0.1) 75%),
        linear-gradient(-45deg, transparent 75%, rgba(255,192,203,0.1) 75%);
    background-size: 20px 20px;
    position: relative;
}

.location-marker {
    position: absolute;
    width: 40px;
    height: 40px;
    transform: translate(-50%, -50%);
    cursor: pointer;
    transition: all 0.3s ease;
}

.location-marker::before {
    content: '';
    position: absolute;
    width: 20px;
    height: 20px;
    background: #fff;
    border-radius: 50%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    box-shadow: 0 2px 8px rgba(255,182,193,0.4);
}

.location-marker::after {
    content: '';
    position: absolute;
    width: 32px;
    height: 32px;
    border: 2px solid currentColor;
    border-radius: 50%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    animation: pulse 2s infinite;
}

.location-label {
    position: absolute;
    bottom: -24px;
    left: 50%;
    transform: translateX(-50%);
    white-space: nowrap;
    background: rgba(255,255,255,0.95);
    padding: 4px 12px;
    border-radius: 12px;
    font-size: 12px;
    box-shadow: 0 2px 8px rgba(255,182,193,0.2);
    color: #444;
    transition: all 0.3s ease;
}

.location-marker:hover {
    transform: translate(-50%, -50%) scale(1.1);
}

.location-marker:hover .location-label {
    transform: translateX(-50%) scale(1.1);
    background: #fff;
    box-shadow: 0 4px 12px rgba(255,182,193,0.3);
}

/* Player character styles */
.player-character {
    position: absolute;
    width: 50px;
    height: 50px;
    transform: translate(-50%, -50%);
    z-index: 100;
    cursor: pointer;
    transition: all 0.5s ease;
}

.player-shadow {
    position: absolute;
    bottom: -4px;
    left: 50%;
    transform: translateX(-50%);
    width: 40px;
    height: 8px;
    background: rgba(255,182,193,0.2);
    border-radius: 50%;
    animation: shadow 3s ease-in-out infinite;
}

.user_avatar {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    border: 3px solid #fff;
    box-shadow: 0 2px 8px rgba(255,182,193,0.4);
    background-size: cover;
    background-position: center;
    animation: float 3s ease-in-out infinite;
}

/* Movement path styles */
.movement-path {
    position: absolute;
    pointer-events: none;
    z-index: 99;
}

.path-line {
    stroke-dasharray: 5;
    animation: dash 1s linear infinite;
    stroke: #ff6b88;
    stroke-width: 2;
    fill: none;
}

.road {
    position: absolute;
    background: linear-gradient(to right, transparent, rgba(255,255,255,0.8) 20%, rgba(255,255,255,0.8) 80%, transparent);
    box-shadow: 0 0 10px rgba(255,182,193,0.2);
    opacity: 0.7;
}

.horizontal-road {
    height: 15px;
    width: 100%;
    transform: rotate(-5deg);
}

.vertical-road {
    width: 15px;
    height: 100%;
    transform: rotate(5deg);
}

/* Character Avatars */
.character-avatar {
    position: absolute;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background-size: cover;
    background-position: center;
    border: 2px solid #fff;
    box-shadow: 0 2px 4px rgba(255,182,193,0.4);
    cursor: pointer;
    transition: all 0.3s ease;
    z-index: 5;
}

.character-avatar:hover {
    transform: scale(1.2);
    box-shadow: 0 4px 8px rgba(255,182,193,0.6);
}

.character-avatar::after {
    content: attr(data-name);
    position: absolute;
    bottom: -20px;
    left: 50%;
    transform: translateX(-50%);
    white-space: nowrap;
    background: rgba(255,255,255,0.95);
    padding: 2px 8px;
    border-radius: 8px;
    font-size: 10px;
    opacity: 0;
    transition: all 0.3s ease;
}

.character-avatar:hover::after {
    opacity: 1;
    bottom: -25px;
}

/* Animations */
@keyframes pulse {
    0% {
        transform: translate(-50%, -50%) scale(1);
        opacity: 0.8;
    }
    50% {
        transform: translate(-50%, -50%) scale(1.2);
        opacity: 0.4;
    }
    100% {
        transform: translate(-50%, -50%) scale(1);
        opacity: 0.8;
    }
}

@keyframes float {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-5px);
    }
}

@keyframes shadow {
    0%, 100% {
        transform: translateX(-50%) scale(1);
        opacity: 0.2;
    }
    50% {
        transform: translateX(-50%) scale(0.8);
        opacity: 0.1;
    }
}

@keyframes dash {
    to {
        stroke-dashoffset: -10;
    }
}

@keyframes sparkle {
    0%, 100% { transform: scale(0); opacity: 0; }
    50% { transform: scale(1); opacity: 1; }
}

/* Location specific colors */
.home { color: #FF9EAA; }
.cafe { color: #FFB7C5; }
.host-club { color: #FF69B4; }
.company { color: #FF8FAB; }
.school { color: #FFB6C1; }
.date-spot { color: #FF69B4; }
.random { color: #FFC0CB; }
.park { color: #FFB7C5; }

/* Decorative elements */
.sparkle {
    position: absolute;
    width: 4px;
    height: 4px;
    background: white;
    border-radius: 50%;
    animation: sparkle 1.5s infinite;
}
</style>
</head>
