            '随机地点': 20,
            '第一人民医院': 5,
            '药店': 5 	
        }
    }
];

document.addEventListener('DOMContentLoaded', function() {
    const mapContent = document.querySelector('.map-content');
    const player = document.querySelector('.player-character');
    const pathLine = document.querySelector('.path-line');
    const backButton = document.querySelector('.back-button');
    const locationMarkers = document.querySelectorAll('.location-marker');
    const clickSound = document.getElementById('clickSound');
    let isMoving = false;
    let characterLocations = new Map();
    let storyPoints = new Map();

    // 创建随机地点弹窗
    const createRandomLocationDialog = () => {
        const dialog = document.createElement('div');
        dialog.style.cssText = `
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: linear-gradient(135deg, #fff5f5 0%, #fff0f5 100%);
            padding: 25px;
            border-radius: 15px;
            box-shadow: 0 4px 20px rgba(255,182,193,0.4);
            z-index: 1000;
            min-width: 280px;
            border: 2px solid rgba(255,182,193,0.3);
        `;

        const title = document.createElement('h3');
        title.textContent = '选择地点类型';
        title.style.cssText = `
            margin-bottom: 20px;
            color: #ff6b88;
            text-align: center;
            font-size: 18px;
            font-weight: 600;
            text-shadow: 0 1px 2px rgba(255,182,193,0.2);
        `;

        const buttonStyle = `
            display: block;
            width: 100%;
            padding: 12px;
            margin-bottom: 12px;
            border: none;
            border-radius: 8px;
            background: linear-gradient(135deg, #ff6b88 0%, #ff8da1 100%);
            color: white;
            cursor: pointer;
            font-size: 15px;
            font-weight: 500;
            transition: all 0.3s ease;
            box-shadow: 0 2px 8px rgba(255,182,193,0.3);
            &:hover {
                transform: translateY(-2px);
                box-shadow: 0 4px 12px rgba(255,182,193,0.4);
            }
            &:active {
                transform: translateY(0);
            }
        `;

        const randomBtn = document.createElement('button');
        randomBtn.textContent = '随机地点';
        randomBtn.style.cssText = buttonStyle;

        const customBtn = document.createElement('button');
        customBtn.textContent = '自定义地点';
        customBtn.style.cssText = buttonStyle;

        const closeBtn = document.createElement('button');
        closeBtn.innerHTML = '×';
        closeBtn.style.cssText = `
            position: absolute;
            top: 8px;
            right: 8px;
            border: none;
            background: none;
            cursor: pointer;
            font-size: 16px;
            color: #ff6b88;
            width: 24px;
            height: 24px;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.3s ease;
            &:hover {
                background: rgba(255,182,193,0.1);
            }
        `;

        dialog.appendChild(title);
        dialog.appendChild(randomBtn);
        dialog.appendChild(customBtn);
        dialog.appendChild(closeBtn);

        const overlay = document.createElement('div');
        overlay.style.cssText = `
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: rgba(0,0,0,0.5);
            backdrop-filter: blur(3px);
            z-index: 999;
        `;

        const closeDialog = () => {
            document.body.removeChild(dialog);
            document.body.removeChild(overlay);
        };

        const randomLocations = [
            '教堂', '温泉', '海边', '游乐园',
            '公园', '酒吧', '动物园', '电影院',
            '水族馆', '烹饪课堂', 'ktv',
            '街角甜品店', '隐秘画廊', '城市书房', 
        ];

        const moveToRandomLocation = () => {
            const randomLocationMarker = Array.from(locationMarkers).find(
                m => m.getAttribute('data-location') === '随机地点'
            );

            if (randomLocationMarker) {
                const rect = mapContent.getBoundingClientRect();
                const markerRect = randomLocationMarker.getBoundingClientRect();

                const x = markerRect.left + markerRect.width/2 - rect.left;
                const y = markerRect.top + markerRect.height/2 - rect.top;

                const playerRect = player.getBoundingClientRect();
                const startX = playerRect.left + playerRect.width/2 - rect.left;
                const startY = playerRect.top + playerRect.height/2 - rect.top;

                pathLine.setAttribute('d', `M ${startX} ${startY} L ${x} ${y}`);

                isMoving = true;
                player.style.left = `${(x/rect.width) * 100}%`;
                player.style.top = `${(y/rect.height) * 100}%`;

                setTimeout(() => {
                    pathLine.setAttribute('d', '');
                    isMoving = false;
                }, 500);
            }
        };

        randomBtn.onclick = () => {
            const randomLocation = randomLocations[Math.floor(Math.random() * randomLocations.length)];

            moveToRandomLocation();

            const charactersAtRandomSpot = [];
            for (const [charName, location] of characterLocations.entries()) {
                if (location === '随机地点') {
                    charactersAtRandomSpot.push(charName);
                }
            }

            if (typeof triggerSlash === 'function') {
                const importance = storyPoints.get('随机地点');
                let message;
                if (charactersAtRandomSpot.length > 0) {
                    message = `出发去${randomLocation} 遇见了${charactersAtRandomSpot.join('、')}${importance ? '[!]'.repeat(importance) : ''}`;
                } else {
                    message = `出发去${randomLocation}${importance ? '[!]'.repeat(importance) : ''}`;
                }
                triggerSlash(`/send ${message}|/trigger`);
            }

            closeDialog();
        };

        customBtn.onclick = () => {
            const inputContainer = document.createElement('div');
            inputContainer.style.cssText = `
                margin-top: -12px;
                margin-bottom: 15px;
            `;

            const input = document.createElement('input');
            input.type = 'text';
            input.placeholder = '请输入地点名称';
            input.style.cssText = `
                display: block;
                width: 100%;
                padding: 10px;
                margin: 10px 0;
                border: 2px solid rgba(255,182,193,0.3);
                border-radius: 8px;
                background: rgba(255,255,255,0.9);
                font-size: 14px;
                color: #666;
                transition: all 0.3s ease;
                &:focus {
                    outline: none;
                    border-color: #ff6b88;
                    box-shadow: 0 0 8px rgba(255,182,193,0.2);
                }
            `;

            const submitBtn = document.createElement('button');
            submitBtn.textContent = '确定';
            submitBtn.style.cssText = buttonStyle;

            inputContainer.appendChild(input);
            dialog.insertBefore(inputContainer, customBtn);
            dialog.insertBefore(submitBtn, customBtn);
            customBtn.style.display = 'none';

            input.focus();

            const handleCustomLocation = () => {
                if (input.value.trim()) {
                    moveToRandomLocation();

                    const charactersAtRandomSpot = [];
                    for (const [charName, location] of characterLocations.entries()) {
                        if (location === '随机地点') {
                            charactersAtRandomSpot.push(charName);
                        }
                    }

                    if (typeof triggerSlash === 'function') {
                        const importance = storyPoints.get('随机地点');
                        let message;
                        if (charactersAtRandomSpot.length > 0) {
                            message = `出发去${input.value.trim()} 遇见了${charactersAtRandomSpot.join('、')}${importance ? '[!]'.repeat(importance) : ''}`;
                        } else {
                            message = `出发去${input.value.trim()}${importance ? '[!]'.repeat(importance) : ''}`;
                        }
                        triggerSlash(`/send ${message}|/trigger`);
                    }
                    closeDialog();
                }
            };

            submitBtn.onclick = handleCustomLocation;

            input.addEventListener('keypress', (e) => {
                if (e.key === 'Enter') {
                    handleCustomLocation();
                }
            });
        };

        closeBtn.onclick = closeDialog;
