    };

    // 播放点击音效函数
    function playClickSound() {
        clickSound.currentTime = 0;
        clickSound.play().catch(error => console.log("Audio playback failed:", error));
    }

    // 创建剧情点元素
    function createStoryPoint(location, importance) {
        const marker = document.createElement('div');
        marker.className = 'story-point';
        marker.innerHTML = '!'.repeat(importance);
        marker.style.position = 'absolute';
        marker.style.zIndex = '10';
        marker.style.color = '#ff4081';
