        marker.style.animation = 'float 2s infinite ease-in-out';

        const locationMarker = Array.from(locationMarkers).find(
            m => m.getAttribute('data-location') === location
        );

        if (locationMarker) {
            const markerRect = locationMarker.getBoundingClientRect();
            const mapRect = mapContent.getBoundingClientRect();
            const angle = Math.random() * Math.PI * 2;
            const distance = 30;
            const x = Math.cos(angle) * distance;
            const y = Math.sin(angle) * distance;

            marker.style.left = `${((markerRect.left - mapRect.left + markerRect.width/2 + x) / mapRect.width) * 100}%`;
            marker.style.top = `${((markerRect.top - mapRect.top + markerRect.height/2 + y) / mapRect.height) * 100}%`;
        }

        return marker;
    }

    // 生成剧情点
    function generateStoryPoints() {
        document.querySelectorAll('.story-point').forEach(point => point.remove());
        storyPoints.clear();

        if (Math.random() < 0.6) {
            const locations = Array.from(locationMarkers).map(marker =>
                marker.getAttribute('data-location')
            );

            const numPoints = Math.floor(Math.random() * 3) + 1;
            for (let i = 0; i < numPoints; i++) {
                if (locations.length === 0) break;

                const randomIndex = Math.floor(Math.random() * locations.length);
                const location = locations.splice(randomIndex, 1)[0];

                let importance;
                const rand = Math.random();
                if (rand < 0.6) importance = 1;
                else if (rand < 0.9) importance = 2;
                else importance = 3;

                storyPoints.set(location, importance);
                const storyPoint = createStoryPoint(location, importance);
                mapContent.appendChild(storyPoint);
            }
        }
    }

    // 根据偏好获取角色位置
    function getCharacterLocation(character) {
        const rand = Math.random() * 100;
        let accumulator = 0;

        for (const [location, probability] of Object.entries(character.preferences)) {
            accumulator += probability;
            if (rand <= accumulator) {
                return location;
            }
        }

        return Object.keys(character.preferences)[
            Math.floor(Math.random() * Object.keys(character.preferences).length)
        ];
    }

    // 生成角色分布
    function generateCharacters() {
