                const y = Math.sin(angle) * distance;

                const markerRect = marker.getBoundingClientRect();
                const mapRect = mapContent.getBoundingClientRect();
                avatar.style.left = `${((markerRect.left - mapRect.left + markerRect.width/2 + x) / mapRect.width) * 100}%`;
                avatar.style.top = `${((markerRect.top - mapRect.top + markerRect.height/2 + y) / mapRect.height) * 100}%`;

                mapContent.appendChild(avatar);

                avatar.addEventListener('click', (e) => {
    e.stopPropagation();
    playClickSound();

    // 获取角色所在位置的标记
    const marker = Array.from(locationMarkers).find(
        m => m.getAttribute('data-location') === location
    );

    if (marker) {
        const rect = mapContent.getBoundingClientRect();
        const markerRect = marker.getBoundingClientRect();

        const x = markerRect.left + markerRect.width/2 - rect.left;
        const y = markerRect.top + markerRect.height/2 - rect.top;

        const playerRect = player.getBoundingClientRect();
        const startX = playerRect.left + playerRect.width/2 - rect.left;
        const startY = playerRect.top + playerRect.height/2 - rect.top;

        pathLine.setAttribute('d', `M ${startX} ${startY} L ${x} ${y}`);

        isMoving = true;
        player.style.left = `${(x/rect.width) * 100}%`;
        player.style.top = `${(y/rect.height) * 100}%`;

        const importance = storyPoints.get(location);
        const message = `出发去${location} 遇见了${character.name}${importance ? '[!]'.repeat(importance) : ''}`;
        if (typeof triggerSlash === 'function') {
            triggerSlash(`/send ${message}|/trigger`);
        }

        setTimeout(() => {
            pathLine.setAttribute('d', '');
            isMoving = false;
        }, 500);
    }
});

            }
        });

        generateStoryPoints();
    }

    // 每50秒重新生成一次角色分布和剧情点
    setInterval(generateCharacters, 50000);
    generateCharacters();

    // 返回按钮点击事件
    backButton.addEventListener('click', function(e) {
        playClickSound();
        if (typeof triggerSlash === 'function') {
            triggerSlash('/send 返回主页|/trigger');
        }
    });

    // 地点标记点击事件
locationMarkers.forEach(marker => {
    marker.addEventListener('click', function(e) {
        e.stopPropagation();
        playClickSound();
        if (isMoving) return;

        const locationName = this.getAttribute('data-location');

        // 如果是随机地点，显示弹窗
        if (locationName === '随机地点') {
