            audio.load();
            return audio;
        });

        function playRandomSound() {
            const randomIndex = Math.floor(Math.random() * soundEffects.length);
            soundEffects[randomIndex].currentTime = 0;
            soundEffects[randomIndex].play();
        }

        function stopDragging() {
            isDragging = false;
        }

