            const blossom = document.createElement('div');
            blossom.classList.add('cherry-blossom');
            blossom.style.left = Math.random() * 100 + 'vw';
            const size = Math.random() * 15 + 5;
            blossom.style.width = size + 'px';
            blossom.style.height = size + 'px';
            blossom.style.animationDuration = (Math.random() * 5 + 4) + 's';
            blossom.style.opacity = Math.random() * 0.5 + 0.3;
            const pink = Math.random() * 15 + 187;
            blossom.style.background = `rgba(255, ${pink}, ${pink + 10}, 0.8)`;
            blossom.style.borderRadius = '50%';
            blossom.style.filter = 'blur(1.5px)';
            document.body.appendChild(blossom);
            setTimeout(() => {
                blossom.remove();
            }, parseFloat(blossom.style.animationDuration) * 1000);
        }

        setInterval(createCherryBlossom, 800);
    </script>
