// 更新时间函数
function updateTime() {
    const now = new Date();
    const hours = now.getHours().toString().padStart(2, '0');
    const minutes = now.getMinutes().toString().padStart(2, '0');
    document.getElementById('current-time').textContent = `${hours}:${minutes}`;
}

// 初始更新时间，然后每分钟更新一次
updateTime();
setInterval(updateTime, 60000);

// 点击音效函数
function playClickSound() {
    const sound = document.getElementById('clickSound');
    sound.currentTime = 0;
    sound.play().catch(err => console.log('音频播放失败:', err));
}

// 点击波纹效果
document.querySelectorAll('.character-avatar').forEach(avatar => {
    avatar.addEventListener('click', function(e) {
        const rect = this.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        const ripple = document.createElement('span');
        ripple.classList.add('ripple');
        ripple.style.left = x + 'px';
        ripple.style.top = y + 'px';

        this.appendChild(ripple);

        setTimeout(() => {
            ripple.remove();
        }, 600);
    });
});

// 查看角色函数
function checkCharacter(characterName) {
    // 播放点击音效
    playClickSound();

    // 添加按钮动画效果
    const avatars = document.querySelectorAll('.character-avatar');
    avatars.forEach(avatar => {
        if (avatar.parentElement.querySelector('.character-name').textContent === characterName) {
            avatar.classList.add('pulse');
            setTimeout(() => avatar.classList.remove('pulse'), 500);
        }
    });

    // 发送消息到聊天
    sendMessage(`观察${characterName}的实时状况`);
}

// 发送消息函数
function sendMessage(message) {
    console.log(`发送消息: ${message}`);

    // 如果在SillyTavern环境中，使用其API
    if (window.parent) {
        try {
            // 尝试通过postMessage发送
            window.parent.postMessage({
                type: 'sendMessage',
                message: message
            }, '*');

            // 备用方法：如果存在triggerSlash函数
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/send ${message}|/trigger`);
            }
        } catch (error) {
            console.error('发送消息失败:', error);
        }
    }
}
</script>
