                return titleText.replace('的实况', '');
            }

            // 设置实时时间
            function updateTime() {
                const now = new Date();
                const hours = now.getHours().toString().padStart(2, '0');
                const minutes = now.getMinutes().toString().padStart(2, '0');
                statusTime.textContent = `${hours}:${minutes}`;
            }
            updateTime();
            setInterval(updateTime, 60000);

            // 处理特殊格式文本
            function formatSpecialText(text) {
                // 处理引号包围的文本为绿色
                text = text.replace(/"(.*?)"/g, '<span class="green-text">$1</span>');
                return text;
            }

            // 格式化初始内容
            if(realityFeed) {
                realityFeed.innerHTML = formatSpecialText(realityFeed.textContent);
            }

            // 发送按钮点击事件
            if(sendButton) {
                sendButton.addEventListener('click', function() {
                    sendMessage();
                });
            }

            // 按Enter键发送消息
            if(messageInput) {
                messageInput.addEventListener('keypress', function(e) {
                    if (e.key === 'Enter') {
                        sendMessage();
                    }
                });
            }

            // 发送消息函数
            function sendMessage() {
                const messageText = messageInput.value.trim();
                if (messageText) {
                    // 获取角色名称
                    const characterName = getCharacterName();

                    // 添加发送的消息
                    addMessage(messageText, true);

                    // 清空输入框
                    messageInput.value = '';

                    // 显示正在输入指示器
                    showTypingIndicator();

                    // 发送消息到SillyTavern系统，使用更新后的格式
                    setTimeout(function() {
                        // 移除输入指示器
                        removeTypingIndicator();

                        // 使用SillyTavern的触发器
                        try {
                            const triggerCommand = `/send 回复${characterName}的实况：${messageText}|/trigger`;

                            if (typeof window.triggerSlash === 'function') {
                                window.triggerSlash(triggerCommand);
                            } else if (typeof triggerSlash === 'function') {
                                triggerSlash(triggerCommand);
                            } else {
                                console.log('触发器命令: ' + triggerCommand);
                            }

                            // 显示发送成功提示
                            showSendSuccess();
                        } catch(e) {
                            console.log('SillyTavern触发器不可用');
                        }
                    }, 1500);
                }
            }

            // 显示发送成功提示
            function showSendSuccess() {
                const successElement = document.createElement('div');
                successElement.style.position = 'absolute';
                successElement.style.bottom = '70px';
                successElement.style.left = '50%';
                successElement.style.transform = 'translateX(-50%)';
                successElement.style.background = 'rgba(52, 199, 89, 0.8)';
                successElement.style.color = 'white';
                successElement.style.padding = '6px 12px';
                successElement.style.borderRadius = '4px';
                successElement.style.fontSize = '12px';
                successElement.style.zIndex = '1000';
                successElement.textContent = '消息已发送';

                document.body.appendChild(successElement);

                setTimeout(function() {
                    successElement.style.opacity = '0';
                    successElement.style.transition = 'opacity 0.5s ease';

                    setTimeout(function() {
                        document.body.removeChild(successElement);
                    }, 500);
                }, 1500);
            }

            // 添加消息
            function addMessage(text, isSent) {
                const messageElement = document.createElement('div');
                messageElement.className = `message ${isSent ? 'sent' : 'received'}`;

                const avatarElement = document.createElement('div');
                avatarElement.className = 'message-avatar';
                if (isSent) {
                    avatarElement.textContent = '瞳';
                }

                const bubbleElement = document.createElement('div');
                bubbleElement.className = 'message-bubble';
                bubbleElement.innerHTML = formatSpecialText(text);

                messageElement.appendChild(avatarElement);
                messageElement.appendChild(bubbleElement);

                contentArea.appendChild(messageElement);
                scrollToBottom();
            }

            // 显示正在输入指示器
            function showTypingIndicator() {
                const typingElement = document.createElement('div');
                typingElement.className = 'message received';
                typingElement.id = 'typingIndicator';

                const avatarElement = document.createElement('div');
                avatarElement.className = 'message-avatar';

                const indicatorElement = document.createElement('div');
                indicatorElement.className = 'typing-indicator';
                indicatorElement.innerHTML = `
                    <div class="typing-bubble"></div>
                    <div class="typing-bubble"></div>
                    <div class="typing-bubble"></div>
                `;

                typingElement.appendChild(avatarElement);
                typingElement.appendChild(indicatorElement);

                contentArea.appendChild(typingElement);
                scrollToBottom();
            }

            // 移除正在输入指示器
            function removeTypingIndicator() {
                const typingElement = document.getElementById('typingIndicator');
                if (typingElement) {
                    typingElement.remove();
                }
            }

            // 滚动到底部
            function scrollToBottom() {
                contentArea.scrollTop = contentArea.scrollHeight;
            }
        });
    </script>
</body>
</html>
```

